<script setup lang="ts">
import { computed } from 'vue'
import JsonValueEditor from './JsonValueEditor.vue'
import { t } from '../lib/i18n'
const props=defineProps<{modelValue:unknown;kind:'columns'|'segments'|'actions'|'badges'|'byteRange'}>()
const emit=defineEmits<{'update:modelValue':[value:any]}>()
const items=computed<any[]>(()=>props.kind==='badges'?Object.entries((props.modelValue as Record<string,any>)??{}).map(([key,value])=>({key,...value})):Array.isArray(props.modelValue)?props.modelValue:[])
const definitions:Record<string,{key:string;label:string;type?:string;options?:string[]}[]>={
  columns:[{key:'key',label:'字段'},{key:'title',label:'标题'},{key:'type',label:'类型',options:['text','number','boolean','enum','badge','file','actions']},{key:'editable',label:'可编辑',type:'boolean'},{key:'width',label:'宽度',type:'number'},{key:'enabledField',label:'启用字段'},{key:'visibleField',label:'可见字段'}],
  segments:[{key:'id',label:'标识'},{key:'label',label:'标题'},{key:'start',label:'起始地址',type:'number'},{key:'size',label:'字节数',type:'number'},{key:'color',label:'颜色',type:'color'},{key:'enabled',label:'启用',type:'boolean'}],
  actions:[{key:'id',label:'动作标识'},{key:'label',label:'标题'},{key:'icon',label:'图标'},{key:'enabledField',label:'启用字段'},{key:'visibleField',label:'可见字段'}],
  badges:[{key:'key',label:'值'},{key:'label',label:'标题'},{key:'color',label:'颜色',type:'color'},{key:'background',label:'背景色',type:'color'}],
}
function commit(value:any[]){if(props.kind==='badges')emit('update:modelValue',Object.fromEntries(value.map(({key,...badge})=>[key,badge])));else emit('update:modelValue',value)}
function change(index:number,key:string,value:any){commit(items.value.map((item,i)=>i===index?{...item,[key]:value}:item))}
function eventValue(event:Event,type?:string){const target=event.target as HTMLInputElement;return type==='boolean'?target.checked:type==='number'?Number(target.value):target.value}
function add(){const index=items.value.length+1;const defaults:any={columns:{key:`column_${index}`,title:`列 ${index}`,type:'text',editable:false},segments:{id:`segment_${index}`,label:`分段 ${index}`,start:0,size:256,color:'#0f6cbd',enabled:true},actions:{id:`action_${index}`,label:`动作 ${index}`},badges:{key:`state_${index}`,label:`状态 ${index}`,color:'#0f6cbd',background:'#e8f3fb'}};commit([...items.value,defaults[props.kind]])}
function move(index:number,direction:number){const next=[...items.value];const target=index+direction;if(target<0||target>=next.length)return;[next[index],next[target]]=[next[target],next[index]];commit(next)}
function byteValue(key:string,value:number){emit('update:modelValue',{...((props.modelValue as object)??{startByte:0,byteCount:1}),[key]:Math.max(0,Math.trunc(value))})}
</script>
<template><div class="structured-property-editor"><div v-if="kind==='byteRange'" class="structured-fields"><label>{{t('起始字节')}}<input type="number" min="0" :value="(modelValue as any)?.startByte??0" @change="byteValue('startByte',Number(($event.target as HTMLInputElement).value))"></label><label>{{t('字节数')}}<input type="number" min="0" :value="(modelValue as any)?.byteCount??1" @change="byteValue('byteCount',Number(($event.target as HTMLInputElement).value))"></label></div><template v-else><details v-for="(item,index) in items" :key="index" class="structured-record" :open="items.length===1"><summary>{{typeof item.title==='object'?item.title.fallback:item.title??item.label??item.key??item.id}}<span>{{index+1}}</span></summary><div class="structured-fields"><label v-for="definition in definitions[kind]" :key="definition.key">{{t(definition.label)}}<select v-if="definition.options" :value="item[definition.key]" @change="change(index,definition.key,eventValue($event))"><option v-for="option in definition.options" :key="option" :value="option">{{option}}</option></select><input v-else :type="definition.type==='boolean'?'checkbox':definition.type??'text'" :value="item[definition.key]" :checked="Boolean(item[definition.key])" @change="change(index,definition.key,eventValue($event,definition.type))"></label></div>
<template v-if="kind==='columns'"><label v-if="item.type==='enum'">{{t('选项')}}<JsonValueEditor :model-value="item.options??[]" type="array" @update:model-value="change(index,'options',$event)"/></label><label v-if="item.type==='file'">{{t('文件类型')}}<input :value="item.accept??''" placeholder=".bin,.hex,.ihx" @change="change(index,'accept',eventValue($event))"></label><label v-if="item.type==='file'">{{t('允许手动路径')}}<input type="checkbox" :checked="item.allowManualPath" @change="change(index,'allowManualPath',eventValue($event,'boolean'))"></label><StructuredPropertyEditor v-if="item.type==='actions'" kind="actions" :model-value="item.actions??[]" @update:model-value="change(index,'actions',$event)"/><StructuredPropertyEditor v-if="item.type==='badge'" kind="badges" :model-value="item.badges??{}" @update:model-value="change(index,'badges',$event)"/></template>
<div class="structured-actions"><button type="button" :disabled="index===0" @click="move(index,-1)">{{t('上移')}}</button><button type="button" :disabled="index===items.length-1" @click="move(index,1)">{{t('下移')}}</button><button type="button" @click="commit(items.filter((_,i)=>i!==index))">{{t('删除')}}</button></div></details><button type="button" class="structured-add" @click="add">+ {{t('添加')}}</button></template><details class="structured-json"><summary>JSON</summary><JsonValueEditor :model-value="modelValue" :type="['badges','byteRange'].includes(kind)?'object':'array'" @update:model-value="emit('update:modelValue',$event)"/></details></div></template>
<style scoped>.structured-property-editor{min-width:0;border:1px solid #d9e0e8;border-radius:4px;padding:5px;font-size:11px}.structured-record{border-bottom:1px solid #e5e9ee;padding-bottom:4px;margin-bottom:4px}.structured-record>summary{display:flex;justify-content:space-between;cursor:pointer;padding:4px 2px;list-style:none}.structured-record>summary:before{content:'›';margin-right:5px}.structured-record[open]>summary:before{content:'⌄'}.structured-record>summary>span{margin-left:auto;color:#8693a2}.structured-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px}.structured-fields label{min-width:0;display:flex;flex-direction:column;gap:3px}.structured-fields input,.structured-fields select{width:100%;min-width:0;box-sizing:border-box}.structured-fields input[type=checkbox]{width:auto;align-self:flex-start}.structured-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:7px}.structured-property-editor button{font:inherit;border:0;background:transparent;color:#0f6cbd;cursor:pointer;padding:3px}.structured-property-editor button:disabled{opacity:.4}.structured-json{margin-top:5px}.structured-json>summary{cursor:pointer;color:#67778a}.structured-add{width:100%;text-align:left}</style>
